 * Parses the election description read from standard input into a list of
 * declared candidate names and a list of ballots.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** An error carrying the line number to report, or none for whole-input errors. */
export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

/**
 * Parses `input` into `{ candidates, ballots }`, where `candidates` is the
 * ordered list of declared names and `ballots` is a list of
 * `{ count, names }` objects. Throws `ParseError` on any violation of the
 * input grammar.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidates = []
  const candidateSet = new Set()
  const ballots = []
  let candidatesSeen = false

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidatesSeen) {
        fail('candidates must be declared once, before any ballot', lineNumber)
      }
      const names = words.slice(1)
      if (names.length === 0) {
        fail('expected candidates <name>...', lineNumber)
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          fail(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      candidatesSeen = true
    } else if (directive === 'ballot') {
      if (!candidatesSeen) {
        fail('candidates must be declared once, before any ballot', lineNumber)
      }
      if (words.length < 3) {
        fail('expected ballot <count> <candidate>...', lineNumber)
      }
      const countText = words[1]
      if (!COUNT_RE.test(countText)) {
        fail('count must be a positive integer', lineNumber)
      }
      const count = Number(countText)
      const names = words.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          fail(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(`unknown directive ${directive}`, lineNumber)
    }
  }

  if (!candidatesSeen) {
    fail('no candidates')
  }

  return { candidates, ballots }
}
"}

