{"file_path":"src/election.js","content":"/**
 * Runs an instant-runoff count over a parsed election and returns the full
 * round-by-round record.
 */

/**
 * Runs the count described by `{ candidates, ballots }` and returns
 * `{ rounds, winner }`, where `rounds` is a list of
 * `{ tally, exhausted, eliminated }` objects (one per round counted, in
 * order, `eliminated` being `null` on the final round) and `winner` is a
 * candidate name or `null` when no candidate ever reached a majority.
 */
export function runElection({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const tally = {}
    for (const name of continuing) tally[name] = 0
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        tally[choice] += ballot.count
      }
    }

    const activeTotal = ballots.reduce((sum, b) => sum + b.count, 0) - exhausted

    rounds.push({ tally, exhausted, eliminated: null })

    if (activeTotal === 0) break

    const majority = [...continuing].find((name) => tally[name] * 2 > activeTotal)
    if (majority !== undefined) {
      winner = majority
      break
    }

    const eliminated = pickEliminated(continuing, tally, rounds)
    rounds[rounds.length - 1].eliminated = eliminated
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

/**
 * Chooses which candidate to eliminate: the one with the fewest votes in
 * `tally`, breaking ties by comparing the tied candidates' counts across the
 * rounds counted so far (this one included), from the first round onwards,
 * and finally by which name sorts last by code point.
 */
function pickEliminated(continuing, tally, rounds) {
  const minVotes = Math.min(...[...continuing].map((name) => tally[name]))
  let tied = [...continuing].filter((name) => tally[name] === minVotes)

  if (tied.length > 1) {
    for (let r = 0; r < rounds.length; r++) {
      const counts = tied.map((name) => rounds[r].tally[name])
      const roundMin = Math.min(...counts)
      if (!counts.every((c) => c === roundMin)) {
        tied = tied.filter((name) => rounds[r].tally[name] === roundMin)
        r = -1
      }
    }
  }

  tied.sort()
  return tied[tied.length - 1]
}
"}

