{"file_path":"src/format.js","content":"/**
 * Renders the round-by-round record produced by `runElection` into the text
 * printed by each CLI mode.
 */

/** Renders one round as `round K: name=votes ... exhausted=n`. */
export function formatRound(round, number) {
  const names = Object.keys(round.tally).sort((a, b) => {
    if (round.tally[a] !== round.tally[b]) return round.tally[b] - round.tally[a]
    return a < b ? -1 : a > b ? 1 : 0
  })
  const parts = names.map((name) => `${name}=${round.tally[name]}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${number}: ${parts.join(' ')}`
}

/** Renders the outcome line: `winner <name>` or `no winner`. */
export function formatOutcome(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}
"}

